// Read the model's reply (works whether it arrives as a JSON string or an object)
const msg = $json.output?.[0]?.content?.[0]?.text ?? $json.output ?? $json;
let data = msg;

if (typeof msg === 'string') {
  const cleaned = msg.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  data = JSON.parse(cleaned);
}

// Accept the expected keys, with fallbacks in case the model varies the names
const subject = data.subject ?? data.Subject ?? data['Email subject'];
const body = data.email_body ?? data.Email ?? data['Email Content'] ?? data.email;

if (!subject || !body) {
  throw new Error('Model reply is missing "subject" or "email_body": ' + JSON.stringify(data));
}

return { json: { subject, body } };
